#include <SDL3/SDL.h>
#include <cmath>
#ifdef __linux__
#  include <dlfcn.h>   // dlopen/dlclose for libdecor presence check
#endif
#include "imgui.h"
#include "imgui_impl_sdl3.h"
#include "imgui_impl_sdlrenderer3.h"
#include "App.h"
#include "AppIconData.h"   // embedded PNG bytes (generated by CMake)
#include "stb_image.h"

int main(int /*argc*/, char* /*argv*/[])
{
    if (!SDL_Init(SDL_INIT_VIDEO))
    {
        SDL_Log("SDL_Init failed: %s", SDL_GetError());
        return 1;
    }

    // Query the display content scale before creating the window so the initial
    // size is correct for the user's DPI setting (e.g. 200% on a 4K display).
    SDL_DisplayID primaryDisplay = SDL_GetPrimaryDisplay();
    float initScale = (primaryDisplay != 0)
                      ? SDL_GetDisplayContentScale(primaryDisplay)
                      : 1.0f;
    if (initScale < 1.0f) initScale = 1.0f;

    SDL_Window* window = SDL_CreateWindow(
        "WowWtfSync",
        (int)(1100 * initScale), (int)(720 * initScale),
        SDL_WINDOW_RESIZABLE | SDL_WINDOW_HIGH_PIXEL_DENSITY
    );
    if (!window) { SDL_Quit(); return 1; }

#ifdef __linux__
    // On Wayland, window decorations require either server-side compositor
    // support (rare in VMs) or client-side decorations via libdecor.  If SDL
    // chose Wayland but libdecor was not loaded into the process, the window
    // will have no title bar.  Detect this and reinitialise with X11, which
    // uses XWayland on Wayland compositors and always provides decorations.
    // The check is skipped if the user explicitly set SDL_VIDEO_DRIVER so
    // their preference is always honoured.
    if (!SDL_getenv("SDL_VIDEO_DRIVER") &&
        SDL_strcmp(SDL_GetCurrentVideoDriver(), "wayland") == 0)
    {
        // RTLD_NOLOAD: probe whether libdecor is already mapped into the
        // process by SDL — do not load it ourselves.
        void* libdecor = dlopen("libdecor-0.so.0", RTLD_LAZY | RTLD_NOLOAD);
        if (!libdecor)
        {
            // libdecor absent: tear down and retry under X11.
            SDL_DestroyWindow(window);
            SDL_Quit();
            SDL_SetHint("SDL_VIDEO_DRIVER", "x11");
            if (!SDL_Init(SDL_INIT_VIDEO))
            {
                SDL_Log("SDL_Init (X11 fallback) failed: %s", SDL_GetError());
                return 1;
            }
            window = SDL_CreateWindow("WowWtfSync",
                (int)(1100 * initScale), (int)(720 * initScale),
                SDL_WINDOW_RESIZABLE | SDL_WINDOW_HIGH_PIXEL_DENSITY);
            if (!window) { SDL_Quit(); return 1; }
        }
        else
        {
            // libdecor is loaded: Wayland decorations will work; release our probe ref.
            dlclose(libdecor);
        }
    }
#endif

    // Set the window icon from the embedded PNG.
    {
        int w, h, channels;
        unsigned char* pixels = stbi_load_from_memory(
            kAppIconPng, static_cast<int>(kAppIconPngSize),
            &w, &h, &channels, 4);
        if (pixels) {
            SDL_Surface* icon = SDL_CreateSurfaceFrom(
                w, h, SDL_PIXELFORMAT_RGBA32, pixels, w * 4);
            if (icon) {
                SDL_SetWindowIcon(window, icon);
                SDL_DestroySurface(icon);
            }
            stbi_image_free(pixels);
        }
    }

    // Let SDL pick the best available hardware renderer first.
    // If that fails (e.g. missing GPU drivers, VM without acceleration),
    // fall back to the software renderer so the app still runs.
    SDL_Renderer* renderer = SDL_CreateRenderer(window, nullptr);
    if (!renderer)
        renderer = SDL_CreateRenderer(window, "software");
    if (!renderer) {
        SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_ERROR, "WowWtfSync",
            SDL_GetError(), window);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;
    ImGui::StyleColorsDark();

    // Scale font and style for HiDPI displays.
    // Prefer the per-window scale (accounts for multi-monitor setups);
    // fall back to initScale if the query fails.
    float dpiScale = SDL_GetWindowDisplayScale(window);
    if (dpiScale < 1.0f) dpiScale = initScale;
    ImFontConfig fontCfg;
    fontCfg.SizePixels = std::round(13.0f * dpiScale);
    io.Fonts->AddFontDefault(&fontCfg);
    ImGui::GetStyle().ScaleAllSizes(dpiScale);

    ImGui_ImplSDL3_InitForSDLRenderer(window, renderer);
    ImGui_ImplSDLRenderer3_Init(renderer);

    App app(window, renderer, dpiScale);

    bool running = true;
    while (running)
    {
        SDL_Event event;
        while (SDL_PollEvent(&event))
        {
            ImGui_ImplSDL3_ProcessEvent(&event);
            if (event.type == SDL_EVENT_QUIT)
                app.requestQuit();
            if (event.type == SDL_EVENT_WINDOW_CLOSE_REQUESTED &&
                event.window.windowID == SDL_GetWindowID(window))
                app.requestQuit();
        }
        if (app.shouldQuit()) running = false;

        ImGui_ImplSDLRenderer3_NewFrame();
        ImGui_ImplSDL3_NewFrame();
        ImGui::NewFrame();

        app.render();

        ImGui::Render();
        SDL_SetRenderDrawColorFloat(renderer, 0.12f, 0.12f, 0.13f, 1.0f);
        SDL_RenderClear(renderer);
        ImGui_ImplSDLRenderer3_RenderDrawData(ImGui::GetDrawData(), renderer);
        SDL_RenderPresent(renderer);
    }

    ImGui_ImplSDLRenderer3_Shutdown();
    ImGui_ImplSDL3_Shutdown();
    ImGui::DestroyContext();
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
